return $input.all().map(item => {
  const j = item.json || {};
  const data = (j.data && typeof j.data === 'object') ? j.data : {};
  const sourceType = String(j.source_type || '').toLowerCase().trim();
  const attempt = Number(j.attempt) > 0 ? Number(j.attempt) : 1;
  let text = '';
  let docUrl = '';
  if (sourceType === 'email') {
    const parts = [];
    if (data.subject) parts.push('Subject: ' + data.subject);
    if (data.body) parts.push(String(data.body));
    const atts = Array.isArray(data.attachments) ? data.attachments : [];
    for (const a of atts) {
      if (a && a.text) parts.push('[Attachment ' + (a.filename || '') + ']\n' + a.text);
      else if (a && a.url && !docUrl) docUrl = String(a.url);
    }
    text = parts.join('\n\n');
  } else if (sourceType === 'cv') {
    text = String(data.cv_text || '');
    if (!text && data.cv_url) docUrl = String(data.cv_url);
  }
  const missing = [];
  if (!j.request_id) missing.push('request_id');
  if (!sourceType) missing.push('source_type');
  if (Object.keys(data).length === 0) missing.push('data');
  if (sourceType === 'email' && !data.from) missing.push('data.from');
  if (sourceType === 'cv' && !data.job_offer) missing.push('data.job_offer');
  const validType = sourceType === 'email' || sourceType === 'cv';
  if (validType && !text && !docUrl) missing.push(sourceType === 'cv' ? 'data.cv_text or data.cv_url' : 'data.body');
  const valid = validType && missing.length === 0;
  let error = null;
  if (sourceType && !validType) error = 'invalid_source_type';
  else if (missing.length) error = 'missing_input';
  return {
    json: {
      request_id: j.request_id || '',
      user_id: j.user_id || '',
      action: j.action || '',
      source_type: sourceType,
      data: data,
      attempt: attempt,
      hr_feedback: j.hr_feedback || '',
      text: text,
      doc_url: docUrl,
      needs_fetch: valid && !!docUrl,
      valid: valid,
      error: error,
      missing_fields: missing,
    },
  };
});

return $input.all().map(item => {
  const j = item.json;
  const d = j.data || {};
  const text = String(j.text || '');
  const lower = text.toLowerCase();
  const reasons = [];
  const urls = text.match(/https?:\/\/[^\s)"'<>]+/gi) || [];
  const shorteners = ['bit.ly', 'tinyurl.com', 't.co', 'goo.gl', 'ow.ly', 'is.gd', 'buff.ly', 'rb.gy', 'cutt.ly', 'shorturl.at'];
  for (const u of urls) {
    const host = (u.split('/')[2] || '').toLowerCase();
    if (shorteners.some(s => host === s || host.endsWith('.' + s))) reasons.push('Shortened URL: ' + host);
    if (/^\d{1,3}(\.\d{1,3}){3}(:\d+)?$/.test(host)) reasons.push('IP-based URL: ' + host);
  }
  const risky = ['.exe', '.js', '.scr', '.zip', '.rar', '.7z', '.bat', '.cmd', '.vbs', '.jar', '.msi', '.iso', '.docm', '.xlsm'];
  const atts = Array.isArray(d.attachments) ? d.attachments : [];
  for (const a of atts) {
    const fn = String((a && a.filename) || '').toLowerCase();
    if (risky.some(e => fn.endsWith(e))) reasons.push('Risky attachment type: ' + fn);
  }
  const from = String(d.from || '');
  const angle = from.match(/<([^>]+)>/);
  const addr = (angle ? angle[1] : from).trim().toLowerCase();
  const domain = addr.split('@')[1] || '';
  if (angle) {
    const displayName = from.slice(0, from.indexOf('<'));
    const nameEmail = displayName.match(/[\w.+-]+@([\w-]+\.[\w.-]+)/);
    if (nameEmail && nameEmail[1].toLowerCase() !== domain) reasons.push('Display name shows a different domain (' + nameEmail[1] + ') than the sender (' + domain + ')');
  }
  const replyTo = String(d.reply_to || '').toLowerCase();
  if (replyTo && domain && replyTo.indexOf('@' + domain) === -1) reasons.push('Reply-To domain differs from sender domain');
  const keywords = ['verify your account', 'confirm your password', 'your password', 'login immediately', 'account suspended', 'urgent action required', 'wire transfer', 'gift card', 'bank details', 'click here to confirm', 'mot de passe', 'virement urgent', 'verifiez votre compte', 'compte suspendu'];
  for (const k of keywords) { if (lower.indexOf(k) !== -1) reasons.push('Phishing keyword: "' + k + '"'); }
  return { json: Object.assign({}, j, { security_checks: { is_suspicious: reasons.length > 0, reasons: reasons, sender_address: addr, sender_domain: domain, urls_found: urls.length } }) };
});

parameters.text:
=You are an HR email analyst. Analyze the email below.
- summary: 2-3 sentences.
- category: one of recruitment, leave, payroll, complaint, information, other.
- importance: one of low, medium, high, urgent.
- security: flag phishing, credential requests, suspicious links or attachments, and explain why.
- suggested_reply: a professional, courteous reply in the same language as the email. It is only a PROPOSAL for HR review. Never promise hiring, leave approval, pay changes or any other HR decision.

From: {{ $json.data.from }}
To: {{ $json.data.to }}
Subject: {{ $json.data.subject }}
Automated security pre-check: {{ JSON.stringify($json.security_checks) }}
HR feedback from a previous review (apply it if present): {{ $json.hr_feedback || 'none' }}

Email content:
{{ $json.text }}

