const ctx = $('Security Checks').item.json;
const out = $input.item.json.output;
const base = { request_id: ctx.request_id, user_id: ctx.user_id, action: ctx.action, source_type: ctx.source_type, attempt: ctx.attempt, hr_feedback: ctx.hr_feedback };
if (!out || typeof out !== 'object' || !out.suggested_reply) {
  const err = $input.item.json.error;
  return { json: Object.assign({}, base, { analysis_failed: true, analysis_error: String((err && err.message) || err || 'LLM output missing or not parseable'), analysis: {}, proposal: {} }) };
}
const categories = ['recruitment', 'leave', 'payroll', 'complaint', 'information', 'other'];
const levels = ['low', 'medium', 'high', 'urgent'];
const category = categories.indexOf(String(out.category || '').toLowerCase()) !== -1 ? String(out.category).toLowerCase() : 'other';
const importance = levels.indexOf(String(out.importance || '').toLowerCase()) !== -1 ? String(out.importance).toLowerCase() : 'medium';
const sec = ctx.security_checks || { reasons: [] };
const llmSec = out.security || {};
const reasons = Array.from(new Set([].concat(sec.reasons || [], llmSec.reasons || [])));
const reply = out.suggested_reply || {};
return { json: Object.assign({}, base, {
  analysis_failed: false,
  analysis: {
    type: 'email',
    summary: out.summary || '',
    category: category,
    importance: importance,
    security: { is_suspicious: !!sec.is_suspicious || !!llmSec.is_suspicious, reasons: reasons, sender_domain: sec.sender_domain || '' },
    original: { from: ctx.data.from || '', subject: ctx.data.subject || '' },
  },
  proposal: { to: sec.sender_address || '', subject: reply.subject || ('Re: ' + (ctx.data.subject || '')), body: reply.body || '' },
}) };

