const ctx = $('Document Text Ready').item.json;
const out = $input.item.json.output;
const base = { request_id: ctx.request_id, user_id: ctx.user_id, action: ctx.action, source_type: ctx.source_type, attempt: ctx.attempt, hr_feedback: ctx.hr_feedback };
if (!out || typeof out !== 'object' || !out.candidate) {
  const err = $input.item.json.error;
  return { json: Object.assign({}, base, { analysis_failed: true, analysis_error: String((err && err.message) || err || 'LLM output missing or not parseable'), analysis: {}, proposal: {} }) };
}
const c = out.candidate || {};
const job = (ctx.data && ctx.data.job_offer) || {};
const norm = s => String(s || '').toLowerCase().trim();
const candSkills = (Array.isArray(c.skills) ? c.skills : []).map(norm).filter(Boolean);
const required = (Array.isArray(job.required_skills) ? job.required_skills : []).map(norm).filter(Boolean);
const matched = required.filter(r => candSkills.some(s => s === r || (s.length >= 3 && r.length >= 3 && (s.indexOf(r) !== -1 || r.indexOf(s) !== -1))));
const missing = required.filter(r => matched.indexOf(r) === -1);
const pct = required.length ? Math.round(matched.length / required.length * 100) : null;
const years = Number(c.years_experience) || 0;
const minYears = Number(job.min_years_experience) || 0;
const reply = out.suggested_reply || {};
return { json: Object.assign({}, base, {
  analysis_failed: false,
  analysis: {
    type: 'cv',
    candidate: c,
    job_title: job.title || '',
    match: { matched_skills: matched, missing_skills: missing, skill_match_pct: pct, years_experience: years, min_years_experience: minYears, experience_ok: years >= minYears },
  },
  proposal: { to: c.email || ctx.data.candidate_email || '', subject: reply.subject || ('Your application - ' + (job.title || '')), body: reply.body || '' },
}) };
